item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
try:
    with urllib.request.urlopen('https://openrouter.ai/api/v1/models', timeout=20) as response:
        models = json.load(response)['data']
    for model in models:
        if 'decision' in (model['id']+' '+model.get('description','')).lower():
            print(json.dumps({k: model.get(k) for k in ('id','name','description','supported_parameters')})[:5000])
except Exception as exc:
    print(type(exc).__name__ + ': ' + str(exc))
PY"

